class GrantScheduler:
    def __init__(self, master, components):
        self.master = master
        self.components = components

    def run(self, stop_time: float, quantum: float) -> float:
        if quantum <= 0:
            raise ValueError('quantum must be positive')

        now = 0.0
        while now < stop_time:
            requested = min(now + quantum, stop_time)
            granted = self.master.request_time(requested)
            if not now < granted <= requested:
                raise RuntimeError('invalid time grant')

            elapsed = granted - now
            for component in self.components:
                component.do_step(granted, elapsed)
            now = granted

        return now
